const csvString = `Name,Age,Role
John,28,Developer
Jane,34,Designer`;

const results = Papa.parse(csvString, {
    header: true,             // Creates array of objects (using the first row as keys)
    dynamicTyping: true,      // Automatically converts numbers and booleans
    skipEmptyLines: true      // Ignores blank rows
});

console.log(results.data);
